"""Optional independent check that DOCX generated by the C exporter loads in Word-compatible parsers."""
from pathlib import Path
import subprocess
import tempfile
import unittest

class OpenXmlTests(unittest.TestCase):
    def test_document_xml_roundtrip_using_python_docx_if_available(self):
        try:
            from docx import Document
        except ImportError:
            self.skipTest('python-docx not available (C DOCX tests still run)')
        root = Path(__file__).resolve().parents[1]
        with tempfile.TemporaryDirectory() as temp:
            exe = Path(temp) / 'write-docx'
            target = Path(temp) / 'sample.docx'
            subprocess.run(['gcc', '-std=c11', '-Wall', '-Wextra', '-Werror', '-pedantic',
                            '-I', str(root/'include'),
                            str(root/'modules/documents/model.c'),
                            str(root/'modules/documents/docx.c'),
                            str(root/'tests/test_documents_docx.c'), '-o', str(exe)],check=True)
            subprocess.run([str(exe),str(target)],check=True)
            obj = Document(target)
            self.assertEqual(obj.paragraphs[0].text, 'Проверка StyleOS & <Макет>')
            self.assertEqual(obj.paragraphs[1].text, 'Вторая строка с текстом.')
            from docx.enum.section import WD_ORIENT
            self.assertEqual(obj.sections[0].orientation, WD_ORIENT.LANDSCAPE)

if __name__ == '__main__':
    unittest.main()
